1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Regex;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.helper.Validate;
6	import org.jsoup.nodes.CDataNode;
7	import org.jsoup.nodes.Comment;
8	import org.jsoup.nodes.DataNode;
9	import org.jsoup.nodes.LeafNode;
10	import org.jsoup.nodes.Node;
11	import org.jsoup.nodes.TextNode;
12	import org.jsoup.parser.TokenQueue;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.function.Function;
16	import java.util.regex.Matcher;
17	import java.util.regex.Pattern;
18	
19	import static org.jsoup.select.StructuralEvaluator.ImmediateParentRun;
20	import static org.jsoup.internal.Normalizer.normalize;
21	
22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                Evaluator right = parseSimpleSequence();
118	                left = combinator(left, combinator, right);
119	            } else {
120	                break;
121	            }
122	        }
123	        return left;
124	    }
125	
126	    Evaluator parseSimpleSequence() {
127	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
128	        Evaluator left = null;
129	        tq.consumeWhitespace();
130	
131	        // one optional type selector
132	        if (tq.matchesWord() || tq.matches("*|"))
133	            left = byTag();
134	        else if (tq.matchChomp('*'))
135	            left = new Evaluator.AllElements();
136	
137	        // zero or more subclasses (#, ., [)
138	        while(true) {
139	            Evaluator right = parseSubclass();
140	            if (right != null) {
141	                left = and(left, right);
142	            }
143	            else break; // no more simple tokens
144	        }
145	
146	        if (left == null)
147	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
148	        return left;
149	    }
150	
151	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
152	        switch (combinator) {
153	            case '>':
154	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
155	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
156	                run.add(right);
157	                return run;
158	            case ' ':
159	                return and(new StructuralEvaluator.Ancestor(left), right);
160	            case '+':
161	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
162	            case '~':
163	                return and(new StructuralEvaluator.PreviousSibling(left), right);
164	            default:
165	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
166	        }
167	    }
168	
169	    @Nullable Evaluator parseSubclass() {
170	        //  Subclass: ID | Class | Attribute | Pseudo
171	        if      (tq.matchChomp('#'))    return byId();
172	        else if (tq.matchChomp('.'))    return byClass();
173	        else if (tq.matches('['))       return byAttribute();
174	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
175	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
176	        else                            return null;
177	    }
178	
179	    /** Merge two evals into an Or. */
180	    static Evaluator or(Evaluator left, Evaluator right) {
181	        if (left instanceof CombiningEvaluator.Or) {
182	            ((CombiningEvaluator.Or) left).add(right);
183	            return left;
184	        }
185	        return new CombiningEvaluator.Or(left, right);
186	    }
187	
188	    /** Merge two evals into an And. */
189	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
190	        if (left == null) return right;
191	        if (left instanceof CombiningEvaluator.And) {
192	            ((CombiningEvaluator.And) left).add(right);
193	            return left;
194	        }
195	        return new CombiningEvaluator.And(left, right);
196	    }
197	
198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "lang":
232	                return lang();
233	            case "nth-child":
234	                return cssNthChild(false, false);
235	            case "nth-last-child":
236	                return cssNthChild(true, false);
237	            case "nth-of-type":
238	                return cssNthChild(false, true);
239	            case "nth-last-of-type":
240	                return cssNthChild(true, true);
241	            case "first-child":
242	                return new Evaluator.IsFirstChild();
243	            case "last-child":
244	                return new Evaluator.IsLastChild();
245	            case "first-of-type":
246	                return new Evaluator.IsFirstOfType();
247	            case "last-of-type":
248	                return new Evaluator.IsLastOfType();
249	            case "only-child":
250	                return new Evaluator.IsOnlyChild();
251	            case "only-of-type":
252	                return new Evaluator.IsOnlyOfType();
253	            case "empty":
254	                return new Evaluator.IsEmpty();
255	            case "blank":
256	                return new NodeEvaluator.BlankValue();
257	            case "root":
258	                return new Evaluator.IsRoot();
259	            case "scope":
260	                return new StructuralEvaluator.Scope();
261	            case "matchText": {
262	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
263	                Evaluator.MatchText matchText = new Evaluator.MatchText();
264	                return matchText;
265	            }
266	            default:
267	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
268	        }
269	    }
270	
271	    // ::comment etc
272	    private Evaluator parseNodeSelector() {
273	        final String pseudo = tq.consumeCssIdentifier();
274	        inNodeContext = true;  // Enter node context
275	
276	        Evaluator left;
277	        switch (pseudo) {
278	            case "node":
279	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
280	                break;
281	            case "leafnode":
282	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
283	                break;
284	            case "text":
285	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
286	                break;
287	            case "comment":
288	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
289	                break;
290	            case "data":
291	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
292	                break;
293	            case "cdata":
294	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
295	                break;
296	            default:
297	                throw new Selector.SelectorParseException(
298	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
299	        }
300	
301	        // Handle following subclasses in node context (like ::comment:contains())
302	        Evaluator right;
303	        while ((right = parseSubclass()) != null) {
304	            left = and(left, right);
305	        }
306	
307	        inNodeContext = false;
308	        return left;
309	    }
310	
311	    private Evaluator byId() {
312	        String id = tq.consumeCssIdentifier();
313	        Validate.notEmpty(id);
314	        return new Evaluator.Id(id);
315	    }
316	
317	    private Evaluator byClass() {
318	        String className = tq.consumeCssIdentifier();
319	        Validate.notEmpty(className);
320	        return new Evaluator.Class(className.trim());
321	    }
322	
323	    private Evaluator byTag() {
324	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
325	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
326	        // consistency - both the selector and the element tag
327	        String tagName = normalize(tq.consumeElementSelector());
328	        Validate.notEmpty(tagName);
329	
330	        // namespaces:
331	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
332	            String plainTag = tagName.substring(2); // strip *|
333	            return new CombiningEvaluator.Or(
334	                new Evaluator.Tag(plainTag),
335	                new Evaluator.TagEndsWith(":" + plainTag)
336	            );
337	        } else if (tagName.endsWith("|*")) { // ns|*
338	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
339	            return new Evaluator.TagStartsWith(ns);
340	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
341	            tagName = tagName.replace("|", ":");
342	        }
343	
344	        return new Evaluator.Tag(tagName);
345	    }
346	
347	    private Evaluator byAttribute() {
348	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
349	            return evaluatorForAttribute(cq);
350	        }
351	    }
352	
353	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
354	        cq.consumeWhitespace();
355	        String key = consumeAttributeKey(cq);
356	        key = normalize(key);
357	        Validate.notEmpty(key);
358	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
359	        cq.consumeWhitespace();
360	        final Evaluator eval;
361	
362	        if (cq.isEmpty()) {
363	            if (key.startsWith("^"))
364	                eval = new Evaluator.AttributeStarting(key.substring(1));
365	            else if (key.equals("*")) // any attribute
366	                eval = new Evaluator.AttributeStarting("");
367	            else
368	                eval = new Evaluator.Attribute(key);
369	        } else if (cq.matchChomp("~=")) { // regex match; the remainder of the queue (less surrounding whitespace) is the pattern
370	            eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder().trim()));
371	        } else {
372	            final String op;
373	            if (cq.matchChomp("!=")) op = "!=";
374	            else if (cq.matchChomp("^=")) op = "^=";
375	            else if (cq.matchChomp("$=")) op = "$=";
376	            else if (cq.matchChomp("*=")) op = "*=";
377	            else if (cq.matchChomp("=")) op = "=";
378	            else throw new Selector.SelectorParseException(
379	                "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
380	
381	            cq.consumeWhitespace();
382	            final String rawValue = consumeAttributeValue(cq);
383	            final boolean quoted = !rawValue.isEmpty() && (rawValue.charAt(0) == '"' || rawValue.charAt(0) == '\'');
384	            // Quoted (CSS string) values keep their quotes and are decoded in the evaluator; bare values have their
385	            // CSS escapes decoded here, so escaped and unescaped forms of the same value match equally.
386	            final String value = quoted ? rawValue : TokenQueue.unescapeCss(rawValue);
387	            cq.consumeWhitespace();
388	
389	            // Quoted (CSS string) values compare case-sensitively by default; bare values keep jsoup's historical
390	            // case-insensitive compare. An 'i' or 's' modifier after the value overrides the default.
391	            boolean caseSensitive = quoted;
392	            if (!cq.isEmpty()) {
393	                String modifier = cq.consumeCssIdentifier();
394	                if (modifier.equalsIgnoreCase("s")) caseSensitive = true;
395	                else if (modifier.equalsIgnoreCase("i")) caseSensitive = false;
396	                else throw new Selector.SelectorParseException(
397	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, modifier + cq.remainder());
398	                cq.consumeWhitespace();
399	                if (!cq.isEmpty())
400	                    throw new Selector.SelectorParseException(
401	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
402	            }
403	
404	            switch (op) {
405	                case "=":
406	                    eval = new Evaluator.AttributeWithValue(key, value, caseSensitive);
407	                    break;
408	                case "!=":
409	                    eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive);
410	                    break;
411	                case "^=":
412	                    eval = new Evaluator.AttributeWithValueStarting(key, value, caseSensitive);
413	                    break;
414	                case "$=":
415	                    eval = new Evaluator.AttributeWithValueEnding(key, value, caseSensitive);
416	                    break;
417	                case "*=":
418	                    eval = new Evaluator.AttributeWithValueContaining(key, value, caseSensitive);
419	                    break;
420	                default:
421	                    throw new Selector.SelectorParseException(
422	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
423	            }
424	        }
425	        return eval;
426	    }
