428	    /**
429	     Consumes an attribute key off the queue, up to (but not including) whitespace or a comparison operator. CSS
430	     escapes in the key are decoded.
431	     */
432	    private String consumeAttributeKey(TokenQueue cq) {
433	        StringBuilder sb = StringUtil.borrowBuilder();
434	        OUT: while (!cq.isEmpty()) {
435	            if (cq.matchesWhitespace()) break;
436	            for (String eval : AttributeEvals) {
437	                if (cq.matches(eval)) break OUT;
438	            }
439	            if (cq.matches('\\')) cq.consumeCssEscapeSequence(sb);
440	            else sb.append(cq.consume());
441	        }
442	        return StringUtil.releaseBuilder(sb);
443	    }
444	
445	    /**
446	     Consumes an attribute value off the queue: either a quoted string (returned with its quotes, for decoding in the
447	     evaluator), or a bare value running to the next whitespace or the end of the queue.
448	     */
449	    private String consumeAttributeValue(TokenQueue cq) {
450	        if (cq.isEmpty()) return "";
451	
452	        if (cq.matches('"') || cq.matches('\'')) {
453	            StringBuilder sb = StringUtil.borrowBuilder();
454	            char quote = cq.consume();
455	            sb.append(quote);
456	            boolean closed = false;
457	            while (!cq.isEmpty()) {
458	                char c = cq.consume();
459	                sb.append(c);
460	                if (c == '\\' && !cq.isEmpty()) {
461	                    sb.append(cq.consume()); // keep the escaped character with its escape, for balanced decoding
462	                } else if (c == quote) {
463	                    closed = true;
464	                    break;
465	                }
466	            }
467	            if (!closed) {
468	                StringUtil.releaseBuilderVoid(sb);
469	                throw new Selector.SelectorParseException("Quoted value must have content");
470	            }
471	            return StringUtil.releaseBuilder(sb);
472	        }
473	
474	        // bare value, up to the next whitespace or the end of the queue
475	        StringBuilder sb = StringUtil.borrowBuilder();
476	        while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
477	        return StringUtil.releaseBuilder(sb);
478	    }
