480	    //pseudo selectors :first-child, :last-child, :nth-child, ...
481	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
482	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
483	
484	    private Evaluator cssNthChild(boolean last, boolean ofType) {
485	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
486	        final int ofIdx = indexOfOfClause(raw);
487	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
488	        final boolean hasOf = ofIdx >= 0;
489	
490	        if (hasOf && ofType)
491	            throw new Selector.SelectorParseException(
492	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
493	
494	        final int step, offset;
495	        if ("odd".equals(arg)) {
496	            step = 2;
497	            offset = 1;
498	        } else if ("even".equals(arg)) {
499	            step = 2;
500	            offset = 0;
501	        } else {
502	            Matcher stepOffsetM, stepM;
503	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
504	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
505	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
506	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
507	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
508	                offset =
509	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
510	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
511	                step = 0;
512	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
513	            } else {
514	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
515	            }
516	        }
517	
518	        if (hasOf) {
519	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
520	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
521	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
522	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
523	        }
524	
525	        return ofType
526	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
527	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
528	    }
529	
530	    /**
531	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
532	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
533	     matched inside quoted strings (so attribute values containing " of " are preserved).
534	     @return the index of the 'o' in 'of', or -1 if there is no of clause
535	     */
536	    private static int indexOfOfClause(String arg) {
537	        boolean inSingle = false;
538	        boolean inDouble = false;
539	        boolean prevEscaped = false;
540	        for (int i = 0; i < arg.length(); i++) {
541	            char c = arg.charAt(i);
542	            if (c == '\\' && i + 1 < arg.length()) {
543	                i++; // skip the escaped char
544	                prevEscaped = true;
545	                continue;
546	            }
547	            if (!inDouble && c == '\'')
548	                inSingle = !inSingle;
549	            else if (!inSingle && c == '"')
550	                inDouble = !inDouble;
551	
552	            if (!inSingle && !inDouble && !prevEscaped
553	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
554	                && arg.regionMatches(true, i, "of", 0, 2)
555	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
556	                return i;
557	            }
558	            prevEscaped = false;
559	        }
560	        return -1;
561	    }
562	
563	    private String consumeParens() {
564	        return tq.chompBalanced('(', ')');
565	    }
566	
567	    private int consumeIndex() {
568	        String index = consumeParens().trim();
569	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
570	        return Integer.parseInt(index);
571	    }
