573	    // pseudo selector :has(el)
574	    private Evaluator has() {
575	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
576	    }
577	
578	    // pseudo selector :is()
579	    private Evaluator is() {
580	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
581	    }
582	
583	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
584	        Validate.isTrue(tq.matchChomp('('), err);
585	        Evaluator eval = parseSelectorGroup();
586	        Validate.isTrue(tq.matchChomp(')'), err);
587	        return func.apply(eval);
588	    }
589	
590	    // pseudo selector :contains(text), containsOwn(text)
591	    private Evaluator contains(boolean own) {
592	        String query = own ? ":containsOwn" : ":contains";
593	        String searchText = TokenQueue.unescape(consumeParens());
594	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
595	
596	        if (inNodeContext)
597	            return new NodeEvaluator.ContainsValue(searchText);
598	
599	        return own
600	            ? new Evaluator.ContainsOwnText(searchText)
601	            : new Evaluator.ContainsText(searchText);
602	    }
603	
604	    private Evaluator containsWholeText(boolean own) {
605	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
606	        String searchText = TokenQueue.unescape(consumeParens());
607	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
608	        return own
609	            ? new Evaluator.ContainsWholeOwnText(searchText)
610	            : new Evaluator.ContainsWholeText(searchText);
611	    }
612	
613	    // pseudo selector :containsData(data)
614	    private Evaluator containsData() {
615	        String searchText = TokenQueue.unescape(consumeParens());
616	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
617	        return new Evaluator.ContainsData(searchText);
618	    }
619	
620	    // :matches(regex), matchesOwn(regex)
621	    private Evaluator matches(boolean own) {
622	        String query = own ? ":matchesOwn" : ":matches";
623	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
624	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
625	        Regex pattern = Regex.compile(regex);
626	
627	        if (inNodeContext)
628	            return new NodeEvaluator.MatchesValue(pattern);
629	
630	        return own
631	            ? new Evaluator.MatchesOwn(pattern)
632	            : new Evaluator.Matches(pattern);
633	    }
634	
635	    // :matches(regex), matchesOwn(regex)
636	    private Evaluator matchesWholeText(boolean own) {
637	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
638	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
639	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
640	
641	        Regex pattern = Regex.compile(regex);
642	        return own
643	            ? new Evaluator.MatchesWholeOwnText(pattern)
644	            : new Evaluator.MatchesWholeText(pattern);
645	    }
646	
647	    // :not(selector)
648	    private Evaluator not() {
649	        String subQuery = consumeParens();
650	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
651	
652	        return new StructuralEvaluator.Not(parse(subQuery));
653	    }
654	
655	    // pseudo selector :lang(en), :lang("en-US")
656	    private Evaluator lang() {
657	        String arg = consumeParens().trim(); // whitespace just inside the parens is ignored
658	        Validate.notEmpty(arg, ":lang() must have a language range");
659	
660	        final String range;
661	        final char first = arg.charAt(0);
662	        if (first == '\'' || first == '"') {
663	            // a quoted range must close at the very end of the argument, with nothing after it
664	            Validate.isTrue(arg.length() > 1 && arg.charAt(arg.length() - 1) == first,
665	                ":lang() has an unclosed quote or trailing content after the language range");
666	            range = arg.substring(1, arg.length() - 1);
667	        } else {
668	            range = arg;
669	        }
670	
671	        Validate.notEmpty(range, ":lang() must have a language range");
672	        for (int i = 0; i < range.length(); i++) {
673	            char c = range.charAt(i);
674	            Validate.isFalse(c == ',' || StringUtil.isWhitespace(c),
675	                ":lang() language range must not contain whitespace or commas");
676	        }
677	        return new Evaluator.Lang(range);
678	    }
679	
680	    @Override
681	    public String toString() {
682	        return query;
683	    }
684	
