77	    /** The explicit :scope pseudo-class; matches the element the (sub-)query is anchored to. Equivalent to the
78	     implicit Root that a leading combinator applies to. */
79	    static class Scope extends Evaluator {
80	        @Override
81	        public boolean matches(Element root, Element element) {
82	            return root == element;
83	        }
84	
85	        @Override protected int cost() {
86	            return 1;
87	        }
88	
89	        @Override public String toString() {
90	            return ":scope";
91	        }
92	    }
93	
94	    static class Has extends StructuralEvaluator {
95	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
96	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
97	        // the element here is just a placeholder so this can be final - gets set in restart()
98	
99	        private final List<Evaluator> branches; // the top-level (comma separated) relative selectors
100	        private final boolean[] wantsSiblings; // per branch: if anchored to the scope by a leading + or ~ combinator
101	        private final boolean[] nodeChains; // per branch: if the chain matches leaf nodes (::comment, ::text etc)
102	
103	        public Has(Evaluator evaluator) {
104	            super(evaluator);
105	            // Split the selector group into its top-level branches, so that each can be tested against the correct
106	            // candidate set (the scope element's descendants, or its following siblings)
107	            if (evaluator instanceof CombiningEvaluator.Or)
108	                branches = ((CombiningEvaluator.Or) evaluator).evaluators;
109	            else
110	                branches = Collections.singletonList(evaluator);
111	            wantsSiblings = new boolean[branches.size()];
112	            nodeChains = new boolean[branches.size()];
113	            for (int i = 0; i < branches.size(); i++) {
114	                Evaluator branch = branches.get(i);
115	                wantsSiblings[i] = anchoredToFollowingSiblings(branch);
116	                nodeChains[i] = chainContainsLeaf(branch);
117	                if (nodeChains[i])
118	                    forceNodeAdjacency(branch); // a leaf in the chain makes every + step compare the full node sequence
119	            }
120	        }
121	
122	        @Override public boolean matches(Element root, Element element) {
123	            // we want to minimize GCs so reusing the Iterator obj
124	            NodeIterator<Node> it = NodeIterPool.borrow();
125	            try {
126	                for (int i = 0; i < branches.size(); i++) {
127	                    Evaluator branch = branches.get(i);
128	                    if (wantsSiblings[i]) {
129	                        // a leading + or ~ combinator anchors the branch to the element's following siblings (and their
130	                        // descendants); only these branches may see outside the element's own subtree
131	                        if (nodeChains[i]) {
132	                            // the chain matches leaf nodes (text, comments, etc), so those are candidates too and the
133	                            // siblings are walked as the complete node sequence rather than the element sequence
134	                            for (Node sib = element.nextSibling(); sib != null; sib = sib.nextSibling()) {
135	                                it.restart(sib);
136	                                while (it.hasNext()) {
137	                                    if (branch.matches(element, it.next()))
138	                                        return true;
139	                                }
140	                            }
141	                        } else {
142	                            for (Element sib = element.nextElementSibling(); sib != null; sib = sib.nextElementSibling()) {
143	                                it.restart(sib);
144	                                while (it.hasNext()) {
145	                                    if (branch.matches(element, it.next()))
146	                                        return true;
147	                                }
148	                            }
149	                        }
150	                    } else {
151	                        // otherwise we only want to match children (or below), and not the input element
152	                        it.restart(element);
153	                        while (it.hasNext()) {
154	                            Node node = it.next();
155	                            if (node == element) continue; // don't match self, only descendants
156	                            if (branch.matches(element, node))
157	                                return true;
158	                        }
159	                    }
160	                }
161	            } finally {
162	                NodeIterPool.release(it);
163	            }
164	            return false;
165	        }
