172	        /* Test if a :has branch is anchored to the scope root by a leading + or ~ combinator (a PreviousSibling or
173	         ImmediatePreviousSibling whose left side is the Root / :scope anchor). Only such a branch is evaluated against
174	         the scope element's siblings; others see its descendants only, so that e.g. :has(h1 ~ h2) cannot match elements
175	         outside the scope's subtree. The :is(), :not(), and nested :has() containers establish their own anchor and do
176	         not borrow the outer sibling relation, so traversal stops at them; a later + or ~ within the branch, such as
177	         "> p + x", is an internal combinator and is not mistaken for the anchor either. */
178	        private static boolean anchoredToFollowingSiblings(Evaluator eval) {
179	            if (eval instanceof PreviousSibling || eval instanceof ImmediatePreviousSibling) {
180	                Evaluator left = ((StructuralEvaluator) eval).evaluator;
181	                if (isScopeAnchor(left))
182	                    return true;
183	                return anchoredToFollowingSiblings(left);
184	            }
185	            if (eval instanceof CombiningEvaluator) {
186	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
187	                    if (anchoredToFollowingSiblings(inner))
188	                        return true;
189	                }
190	            } else if (eval instanceof ImmediateParentRun) {
191	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators) {
192	                    if (anchoredToFollowingSiblings(inner))
193	                        return true;
194	                }
195	            } else if (eval instanceof Ancestor) {
196	                return anchoredToFollowingSiblings(((StructuralEvaluator) eval).evaluator);
197	            }
198	            return false; // Is, Not, Has (own anchors), and leaf / simple evaluators
199	        }
200	
201	        /* The implicit Root of a leading combinator, or an explicit :scope, possibly compounded with simple filters
202	         (e.g. :scope:not(.x)). Must not descend into structural evaluators, where the scope is only a deeper operand. */
203	        private static boolean isScopeAnchor(Evaluator eval) {
204	            if (eval instanceof Root || eval instanceof Scope)
205	                return true;
206	            if (eval instanceof CombiningEvaluator) {
207	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
208	                    if (isScopeAnchor(inner))
209	                        return true;
210	                }
211	            }
212	            return false;
213	        }
214	
215	        /* Test if the branch's chain contains a leaf-node selector (::comment, ::text, etc). A nested :has() is its own
216	         chain anchored to its own scope, so it is not considered; :is() and :not() contents still qualify candidates of
217	         this chain, and are descended into. */
218	        private static boolean chainContainsLeaf(Evaluator eval) {
219	            if (eval instanceof Has)
220	                return false; // a nested :has() runs its own chain
221	            if (eval instanceof NodeEvaluator)
222	                return true;
223	            if (eval instanceof CombiningEvaluator) {
224	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
225	                    if (chainContainsLeaf(inner))
226	                        return true;
227	                }
228	            } else if (eval instanceof ImmediateParentRun) {
229	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators) {
230	                    if (chainContainsLeaf(inner))
231	                        return true;
232	                }
233	            } else if (eval instanceof StructuralEvaluator) {
234	                return chainContainsLeaf(((StructuralEvaluator) eval).evaluator);
235	            }
236	            return false;
237	        }
238	
239	        /* Once a chain contains a leaf-node selector, every adjacent-sibling (+) step in that chain compares against the
240	         complete sibling sequence -- text, comment, and data leaves count as intervening nodes instead of being
241	         skipped. A nested :has() runs its own chain (prepared by its own constructor); :is() and :not() are chains of
242	         their own and determine their mode from their own contents. */
243	        private static void forceNodeAdjacency(Evaluator eval) {
244	            applyNodeAdjacency(eval, true);
245	        }
246	
247	        private static void applyNodeAdjacency(Evaluator eval, boolean chainHasLeaf) {
248	            if (eval instanceof Has)
249	                return; // a nested :has() runs its own chain
250	            if (eval instanceof Is || eval instanceof Not) {
251	                // the container's contents are their own selector list / chain
252	                Evaluator inner = ((StructuralEvaluator) eval).evaluator;
253	                if (inner instanceof CombiningEvaluator.Or) {
254	                    for (Evaluator branch : ((CombiningEvaluator.Or) inner).evaluators)
255	                        applyNodeAdjacency(branch, chainContainsLeaf(branch));
256	                } else {
257	                    applyNodeAdjacency(inner, chainContainsLeaf(inner));
258	                }
259	                return;
260	            }
261	            if (eval instanceof ImmediatePreviousSibling) {
262	                StructuralEvaluator ips = (StructuralEvaluator) eval;
263	                if (chainHasLeaf)
264	                    ips.wantsNodes = true;
265	                applyNodeAdjacency(ips.evaluator, chainHasLeaf);
266	                return;
267	            }
268	            if (eval instanceof CombiningEvaluator) {
269	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators)
270	                    applyNodeAdjacency(inner, chainHasLeaf);
271	            } else if (eval instanceof ImmediateParentRun) {
272	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators)
273	                    applyNodeAdjacency(inner, chainHasLeaf);
274	            } else if (eval instanceof StructuralEvaluator) {
275	                applyNodeAdjacency(((StructuralEvaluator) eval).evaluator, chainHasLeaf); // Ancestor, PreviousSibling
276	            }
277	        }
278	
279	        @Override protected int cost() {
280	            return 10 * evaluator.cost();
281	        }
282	
283	        @Override
284	        public String toString() {
285	            return String.format(":has(%s)", evaluator);
286	        }
287	    }
288	
289	    /** Implements the :is(sub-query) pseudo-selector */
290	    static class Is extends StructuralEvaluator {
291	        public Is(Evaluator evaluator) {
292	            super(evaluator);
293	        }
294	
295	        @Override
296	        boolean evaluateMatch(Element root, Node node) {
297	            return evaluator.matches(root, node);
298	        }
299	
300	        @Override protected int cost() {
301	            return 2 + evaluator.cost();
302	        }
303	
304	        @Override
305	        public String toString() {
306	            return String.format(":is(%s)", evaluator);
307	        }
308	    }
309	
310	    static class Not extends StructuralEvaluator {
311	        public Not(Evaluator evaluator) {
312	            super(evaluator);
313	        }
314	
315	        @Override
316	        boolean evaluateMatch(Element root, Node node) {
317	            return !memoMatches(root, node);
318	        }
319	
320	        @Override protected int cost() {
321	            return 2 + evaluator.cost();
322	        }
323	
324	        @Override
325	        public String toString() {
326	            return String.format(":not(%s)", evaluator);
327	        }
328	    }
329	
330	    /**
331	     Any Ancestor (i.e., ascending parent chain.).
332	     */
333	    static class Ancestor extends StructuralEvaluator {
334	        public Ancestor(Evaluator evaluator) {
335	            super(evaluator);
336	        }
337	
338	        @Override
339	        boolean evaluateMatch(Element root, Node node) {
340	            if (root == node)
341	                return false;
342	
343	            for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
344	                if (memoMatches(root, parent))
345	                    return true;
346	                if (parent == root)
347	                    break;
348	            }
349	            return false;
350	        }
351	
352	        @Override
353	        protected int cost() {
354	            return 8 * evaluator.cost(); // probably lower than has(), but still significant, depending on doc and el depth.
355	        }
356	
357	        @Override
358	        public String toString() {
359	            return String.format("%s ", evaluator);
360	        }
361	    }
362	
363	    /**
364	     Holds a list of evaluators for one > two > three immediate parent matches, and the final direct evaluator under
365	     test. To match, these are effectively ANDed together, starting from the last, matching up to the first.
366	     */
367	    static class ImmediateParentRun extends StructuralEvaluator {
368	        final ArrayList<Evaluator> evaluators = new ArrayList<>();
369	        int cost = 2;
370	
371	        public ImmediateParentRun(Evaluator evaluator) {
372	            super(evaluator);
373	            evaluators.add(evaluator);
374	            cost += evaluator.cost();
375	        }
376	
377	        void add(Evaluator evaluator) {
378	            evaluators.add(evaluator);
379	            cost += evaluator.cost();
380	            wantsNodes |= evaluator.wantsNodes();
381	        }
382	
383	        @Override boolean evaluateMatch(Element root, Node node) {
384	            if (node == root)
385	                return false; // cannot match as the second eval (first parent test) would be above the root
386	
387	            for (int i = evaluators.size() -1; i >= 0; --i) {
388	                if (node == null)
389	                    return false;
390	                Evaluator eval = evaluators.get(i);
391	                if (!eval.matches(root, node))
392	                    return false;
393	                node = node.parent();
394	            }
395	            return true;
396	        }
397	
398	        @Override protected int cost() {
399	            return cost;
400	        }
401	
402	        @Override
403	        protected void reset() {
404	            for (Evaluator evaluator : evaluators) {
405	                evaluator.reset();
406	            }
407	            super.reset();
408	        }
409	
410	        @Override
411	        public String toString() {
412	            return StringUtil.join(evaluators, " > ");
413	        }
414	    }
415	
416	    static class PreviousSibling extends StructuralEvaluator {
417	        public PreviousSibling(Evaluator evaluator) {
418	            super(evaluator);
419	        }
420	
421	        // matches any previous sibling, so can be same in Element only or wantsNodes context
422	        @Override boolean evaluateMatch(Element root, Node node) {
423	            if (root == node) return false;
424	
425	            for (Node sib = node.firstSibling(); sib != null; sib = sib.nextSibling()) {
426	                if (sib == node) break;
427	                if (memoMatches(root, sib)) return true;
428	            }
429	
430	            return false;
431	        }
432	
433	        @Override protected int cost() {
434	            return 3 * evaluator.cost();
435	        }
436	
437	        @Override
438	        public String toString() {
439	            return String.format("%s ~ ", evaluator);
440	        }
441	    }
442	
443	    static class ImmediatePreviousSibling extends StructuralEvaluator {
444	        public ImmediatePreviousSibling(Evaluator evaluator) {
445	            super(evaluator);
446	        }
447	
448	        @Override boolean evaluateMatch(Element root, Node node) {
449	            if (root == node) return false;
450	
451	            Node prev = wantsNodes ? node.previousSibling() : node.previousElementSibling();
452	            return prev != null && memoMatches(root, prev);
453	        }
454	
455	        @Override protected int cost() {
456	            return 2 + evaluator.cost();
457	        }
458	
459	        @Override
460	        public String toString() {
461	            return String.format("%s + ", evaluator);
462	        }
463	    }
464	}
