import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

import java.util.Arrays;

public class Probe {
    static int failures = 0;

    static void check(String name, boolean cond) {
        System.out.println((cond ? "PASS " : "FAIL ") + name);
        if (!cond) failures++;
    }

    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) {
            if (sb.length() > 0) sb.append(",");
            String id = e.id();
            sb.append(id.isEmpty() ? e.tagName() : id);
        }
        return sb.toString();
    }

    static void expectIds(String name, Document doc, String css, String expected) {
        Elements got = doc.select(css);
        String actual = ids(got);
        check(name + " [" + css + " => " + actual + "]", actual.equals(expected));
    }

    static void expectParseFail(String name, String css) {
        boolean threw = false;
        try {
            org.jsoup.select.QueryParser.parse(css);
        } catch (Selector.SelectorParseException e) {
            threw = true;
        }
        check(name + " [" + css + "]", threw);
    }

    public static void main(String[] args) {
        // 1. descendant scoping: :has(.x) only within candidate's subtree
        Document d1 = Jsoup.parse(
            "<div id=a><p id=p1><span class=x></span></p></div>" +
            "<div id=b><section id=s1><p id=p2><span class=x></span></p></section></div>");
        expectIds("descendant:has", d1, "p:has(.x)", "p1,p2");
        expectIds("child combinator scoped", d1, "div:has(> p.x)", "");
        expectIds("direct child hit", d1, "div:has(> p)", "a");
        expectIds("nested > within section", d1, "section:has(> p > .x)", "s1");

