        StringBuilder sb = new StringBuilder();
        for (Element e : els) {
            if (sb.length() > 0) sb.append(",");
            String id = e.id();
            sb.append(id.isEmpty() ? e.tagName() : id);
        }
        return sb.toString();
    }

    static void expectIds(String name, Document doc, String css, String expected) {
        Elements got = doc.select(css);
        String actual = ids(got);
        check(name + " [" + css + " => " + actual + "]", actual.equals(expected));
    }

    static void expectParseFail(String name, String css) {
        boolean threw = false;
        try {
            org.jsoup.select.QueryParser.parse(css);
        } catch (Selector.SelectorParseException e) {
