import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import org.jsoup.nodes.Document;

public class Probe {
    static final String BASE = "https://example.com/page/index.html";
    static int fails = 0;

    static Safelist httpHttps() {
        return Safelist.none().addTags("a","p","img","div","form","span")
            .addAttributes("a","href","title").addProtocols("a","href","http","https")
            .addAttributes("img","src","alt").addProtocols("img","src","http","https")
            .addAttributes("form","action").addProtocols("form","action","http","https");
    }

    static void show(String label, String html, Safelist sl, String base) {
        String once = Jsoup.clean(html, base, sl);
        String twice = Jsoup.clean(once, base, sl);
        boolean idem = once.equals(twice);
        if (!idem) fails++;
        // reparse stability of href values
        String reparseHref = "";
        Document d = Jsoup.parse(once);
        var a = d.select("a").first();
        if (a != null) reparseHref = a.attr("href");
        System.out.printf("%-40s | %-55s | idem=%s%s%n", label, once, idem, idem?"":("  TWICE="+twice));
    }

    public static void main(String[] args) {
        Safelist sl = httpHttps();
        String[] cases = {
            "multi-colon path|<a href=http://evil.com/a:b:c>x</a>",
            "numeric colon|<a href=123:45:6>x</a>",
            "hostless https|<a href=https:/foo>x</a>",
            "hostless https tri|<a href=https:///foo>x</a>",
            "hostless https opaque|<a href=https:foo>x</a>",
            "bad pct path|<a href=http://example.com/%zz>x</a>",
            "bad pct path2|<a href=/foo%2>x</a>",
            "backslash auth|<a href=https://evil.com\\\\@good.com/>x</a>",
            "backslash after scheme|<a href=https:\\\\evil.com\\\\x>x</a>",
            "leading tab http|<a href=\"\thttps://evil.com/x\">x</a>",
            "inner tab url|<a href=https://evil.com/x\t?a=1>x</a>",
            "nul in host|<a href=https://ev%00il.com/x>x</a>",
            "query only|<a href=?q=1>x</a>",
            "fragment only|<a href=#frag>x</a>",
            "proto relative|<a href=//cdn.example.com/x>x</a>",
            "root relative|<a href=/foo>x</a>",
            "dot segments|<a href=../../a/b>x</a>",
            "space in path|<a href=/foo%20bar>x</a>",
            "cr lf in value|<a href=\"https://evil.com/x\r\n\">x</a>",
            "double url proto-rel jumbled|<a href=//cdn.example.com/a:b:c>x</a>",
            "form action rel|<form action=submit.php></form>",
            "two attrs one bad|<a href=javascript:1 title=keep>x</a>",
            "case scheme|<a href=HTTP://EVIL.COM/X>x</a>",
            "unknown scheme|<a href=tel:123>x</a>",
            "mailto basic|<a href=mailto:a@b.com>m</a>",
            "java newline|<a href=\"java\nscript:1\">x</a>",
            "tab before colon|<a href=\"javascript\t:1\">x</a>",
            "encoded backslash scheme|<a href=java%5Cscript:1>x</a>",
        };
        for (String c : cases) {
            String[] parts = c.split("\\|", 2);
            show(parts[0], parts[1], sl, BASE);
        }

        // preserve relative mode
        Safelist pr = httpHttps().preserveRelativeLinks(true);
        show("PR relative", "<a href=foo/bar?a=1#b>x</a>", pr, BASE);
        show("PR anchor", "<a href=#frag>x</a>", pr, BASE);
