import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import org.jsoup.nodes.Document;

public class Probe2 {
    static final String BASE = "https://example.com/page/index.html";
    static Safelist sl() {
        return Safelist.none().addTags("a","img")
            .addAttributes("a","href").addProtocols("a","href","http","https")
            .addAttributes("img","srcset","alt").addProtocols("img","srcset","http","https");
    }
    public static void main(String[] args) {
        String[] vals = {
            "https://[bad", "https://[::1]/x", "%%%", "%", "http://", "https://?",
            "https://#", "//", "///", "?", "#", ":", "::", "a:", "http:?",
            "http://ex ample.com/", "http://example.com/%", "http://example.com/%z",
            "\u0000", "\u0000javascript:1", "java\u0000script:1",
            "ht\u0001tp://evil.com/", "  \t ", "\u00adjavascript:1", "\ufeffjavascript:1",
            "javascript\u2028:1", "javascript\u2029:1",
            "data:text/html;base64,", "vbscript:", "JaVa\tScRiPt:1",
            "https://example.com/a\\@evil.com/",
            ".", "..", "./", "../", "////evil.com/x",
            "https:/", "https:///", "http:8080/foo",
            "https://example.com/x?y=%", "https://example.com/#%zz",
            "\r\n", "x\u007f", "a%0ab:1",
        };
        Safelist sl = sl();
        int fail = 0;
        for (String v : vals) {
            try {
                String html = "<a href=\"" + v.replace("\"","&quot;") + "\">x</a>";
                String o1 = Jsoup.clean(html, BASE, sl);
                String o2 = Jsoup.clean(o1, BASE, sl);
                String o3 = Jsoup.clean(html, sl.preserveRelativeLinks(true));
                String o4 = Jsoup.clean(o3, sl.preserveRelativeLinks(true));
                boolean ok = o1.equals(o2) && o3.equals(o4);
                if (!ok) { fail++; System.out.println("NON-IDEMPOTENT: ["+v.replace("\n","\\n").replace("\r","\\r").replace("\u0000","\\0")+"] -> "+o1+" / "+o2+" || "+o3+" / "+o4); }
            } catch (Throwable t) {
                fail++;
                System.out.println("THREW on ["+v.replace("\n","\\n").replace("\r","\\r").replace("\u0000","\\0")+"]: "+t);
            }
        }
        // srcset pathological
        String[] sets = {",", ",,", " , ", "javascript:1,", "%,http://ok.com/x", "http://ok.com/x 1x , ", "\u0000http://ok.com/x"};
        for (String v : sets) {
            try {
                String html = "<img srcset=\"" + v.replace("\"","&quot;") + "\" alt=x>";
                String o1 = Jsoup.clean(html, BASE, sl);
                String o2 = Jsoup.clean(o1, BASE, sl);
                if (!o1.equals(o2)) { fail++; System.out.println("SRCSET NON-IDEM: "+v+" -> "+o1+" / "+o2); }
                Document d = Jsoup.parse(o1); // must reparse
            } catch (Throwable t) { fail++; System.out.println("SRCSET THREW on "+v+": "+t); }
        }
        System.out.println(fail==0 ? "NO FAILURES / NO EXCEPTIONS" : fail+" failures");
    }
}

