import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe2 {
    static int failures = 0;
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) {
            if (sb.length() > 0) sb.append(",");
            String id = e.id();
            sb.append(id.isEmpty() ? e.tagName() : id);
        }
        return sb.toString();
    }
    static void expectIds(String name, Document doc, String css, String expected) {
        String actual = ids(doc.select(css));
        boolean ok = actual.equals(expected);
        System.out.println((ok ? "PASS " : "FAIL ") + name + " [" + css + " => " + actual + "]");
        if (!ok) failures++;
    }
    static void expectParseFail(String name, String css) {
        boolean threw = false;
        try { org.jsoup.select.QueryParser.parse(css); }
        catch (Selector.SelectorParseException e) { threw = true; }
        System.out.println((threw ? "PASS " : "FAIL ") + name + " [" + css + "]");
        if (!threw) failures++;
    }

    public static void main(String[] args) {
        // nested :has sibling anchor is the inner section, not outer div
        Document d = Jsoup.parse(
