        Document d13 = Jsoup.parse("<form id=f><table id=t><tr id=r><td id=c>" +
            "<form id=inner><input id=inp name=v></form>" +
            "<button id=btn></button></td></tr></table></form>");
        expectIds("table structure has input", d13, "td:has(input, button)", "c");
        expectIds("tr nested has", d13, "tr:has(td:has(button))", "r");

        // XML parser
        Document xml = Jsoup.parse("<root id='r'><child id='c'><leaf id='l'/></child></root>", "", org.jsoup.parser.Parser.xmlParser());
        expectIds("xml has", xml, "root:has(child leaf)", "r");
        expectIds("xml child combinator", xml, "child:has(> leaf)", "c");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
        System.exit(failures == 0 ? 0 : 1);
    }

    static void check(String name, boolean cond) {
        System.out.println((cond ? "PASS " : "FAIL ") + name);
        if (!cond) failures++;
    }
}

