import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe3 {
    static int failures = 0;
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) {
            if (sb.length() > 0) sb.append(",");
            String id = e.id();
            sb.append(id.isEmpty() ? e.tagName() : id);
        }
        return sb.toString();
    }
    static void expect(String name, Document doc, String css, String expected) {
        String actual = ids(doc.select(css));
        boolean ok = actual.equals(expected);
        System.out.println((ok ? "PASS " : "FAIL ") + name + " [" + css + " => " + actual + "]");
        if (!ok) failures++;
    }

    public static void main(String[] args) {
        // comment INSIDE a later sibling must NOT count as a sibling comment
        Document d = Jsoup.parse("<article id=a></article><section id=s><!-- c --></section>");
        expect("comment nested in later sibling not sibling", d, "article:has(~ ::comment)", "");
        expect("comment nested via + not sibling", d, "article:has(+ ::comment)", "");
        Document d1b = Jsoup.parse("<article id=a></article><!-- c --><section id=s></section>");
        expect("real following comment sibling", d1b, "article:has(~ ::comment)", "a");
        expect("immediate comment sibling", d1b, "article:has(+ ::comment)", "a");

        // + sibling anchor with descendant of sibling
        Document d2 = Jsoup.parse("<div id=a></div><p id=p><b id=b></b></p><div id=c></div>");
        expect("plus anchor then descendant hit", d2, "div:has(+ p b)", "a");
        expect("plus anchor then descendant miss last", d2, "div:has(+ p b)", "a");
        expect("tilde anchor descendant", d2, "div:has(~ p b)", "a,c");

        // descendant of cousin branch cannot leak: b's p must not be seen by a via >
        Document d3 = Jsoup.parse("<div id=a><section id=sec><p id=p></p></section></div>");
        expect("child cannot see nephew", d3, "div:has(> p)", "");
        expect("grandchild via > >", d3, "div:has(> section > p)", "a");

        // :is wrapping :has relative
        Document d4 = Jsoup.parse("<div id=a></div><p id=p></p><div id=b><span></span></div>");
        expect("is wrapping has sibling", d4, "div:is(:has(+ p))", "a");
        expect("is wrapping has descendant", d4, "div:is(:has(span))", "b");
        expect("not wrapping has sibling", d4, "div:not(:has(+ p))", "b");

        // :has with :is containing commas, dedupe once
        Document d5 = Jsoup.parse("<div id=a><p id=p></p><span id=s></span></div>");
        expect("has is comma dedupe", d5, "div:has(:is(p, span))", "a");

        // sibling relation inside :is within :has keeps the :has scope
        Document d6 = Jsoup.parse(
            "<section id=s1><h1 id=h1></h1></section><p id=p1></p>" +
            "<section id=s2></section><div id=mid></div><p id=p2></p>");
        expect("has containing is plus", d6, "section:has(:is(+ p))", "s1,s2");
        // only s2 has an actual div sibling (s1's following is p)
        expect("has containing is div", d6, "section:has(:is(~ div))", "s2");

        // nested :not with combinator inside has
        Document d7 = Jsoup.parse("<ul id=u><li id=a class=x></li><li id=b></li></ul>");
        expect("has li not class", d7, "ul:has(li:not(.x))", "u");
        expect("has li.x then negated", d7, "ul:has(li:not(:not(.x)))", "u");

        // :has argument that is only :scope chains
        Document d8 = Jsoup.parse("<div id=a><p id=p></p></div>");
        expect("scope alone never self-matches", d8, "div:has(:scope)", "");
        expect("scope child", d8, "div:has(:scope p)", "a");

        // same candidate via descendant+child+sibling comma branches once
        Document d9 = Jsoup.parse("<div id=a></div><p id=p><b id=b></b></p>");
        expect("mixed comma branches dedupe", d9, "div:has(+ p, + p b, ~ p)", "a");

        // stress: deeply nested has scopes with siblings at each level
        Document d10 = Jsoup.parse(
            "<div id=o><section id=ss></section><article id=ar></article><h1 id=h></h1></div>" +
            "<div id=o2><section id=ss2><article id=ar2></article></section><h1 id=h2></h1></div>");
        // o: section has sibling article, and that article has sibling h1? ar's siblings: ss, h1 => yes
        expect("layered siblings hit", d10, "div:has(section:has(~ article:has(~ h1)))", "");
        // actually in o, article's following sibling h1 exists => o should match;
        // in o2 article is INSIDE section, its siblings none => no
        expect("layered siblings hit2", d10, "div:has(section ~ article:has(~ h1))", "o");

        // whitespace entities in text don't affect structural relation
        Document d11 = Jsoup.parse("<div id=a>\n   \n<p id=p></p>\n   </div>");
        expect("whitespace text nodes child", d11, "div:has(> p)", "a");
        expect("whitespace text adjacency elements", d11, "div:has(+ p)", "");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
        System.exit(failures == 0 ? 0 : 1);
    }
}

