import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import org.jsoup.nodes.Document;

public class Probe3 {
    static final String BASE = "https://example.com/page/index.html";
    static int fail = 0;
    static void chk(String label, String in, Safelist sl, String base, String expect) {
        String out = Jsoup.clean(in, base, sl);
        String twice = Jsoup.clean(out, base, sl);
        boolean ok = out.equals(twice);
        if (expect != null && !out.equals(expect)) { ok = false; }
        if (!ok) fail++;
        System.out.printf("%-34s | %-60s | idem=%s%s%n", label, out.replace("\n","\\n"), out.equals(twice),
            (expect!=null&&!out.equals(expect))?"  EXPECT="+expect:"");
    }
    public static void main(String[] args) {
        Safelist basic = Safelist.basic();
        // entity encoded schemes (parser decodes attribute entities before safelist sees them)
        String[] enc = {
            "&#106;avascript:alert(1)",
            "&#x6A;avascript:1",
            "javascript&#58;alert(1)",
            "&#106;avascript&#58;alert(1)",
            "&#0000106;avascript:1",
            "JAVASCRIPT&colon;1",
            "&Tab;javascript:1",
            "&#x0a;javascript:1",
        };
        for (String v : enc) chk("encoded "+v.replaceAll("[^a-zA-Z0-9;]",""), "<a href=\""+v+"\">x</a>",
            Safelist.none().addTags("a").addAttributes("a","href").addProtocols("a","href","http","https"), BASE, "<a>x</a>");

        // nofollow: external added, same-site not, and stable on second clean
        chk("nofollow external", "<a href=https://other.com/x>x</a>", basic, BASE,
            "<a href=\"https://other.com/x\" rel=\"nofollow\">x</a>");
        chk("nofollow same-site", "<a href=https://example.com/x>x</a>", basic, BASE,
            "<a href=\"https://example.com/x\">x</a>");
        chk("nofollow relative", "<a href=a.html>x</a>", basic, BASE,
            "<a href=\"https://example.com/page/a.html\">x</a>");
        chk("nofollow rootrel", "<a href=/x>x</a>", basic, BASE,
            "<a href=\"https://example.com/x\">x</a>");
        chk("nofollow proto-rel", "<a href=//other.com/x>x</a>", basic, BASE,
            "<a href=\"https://other.com/x\" rel=\"nofollow\">x</a>");
        chk("nofollow dropped href", "<a href=javascript:1>x</a>", basic, BASE,
            "<a rel=\"nofollow\">x</a>");

        // rel=nofollow present in input pointing same site: second clean must not remove/change
        String once = Jsoup.clean("<a href=https://example.com/x rel=nofollow>x</a>", BASE, basic);
        String twice = Jsoup.clean(once, BASE, basic);
        System.out.println("explicit nofollow same-site once/twice equal: " + once.equals(twice) + " -> " + once);
        if (!once.equals(twice)) fail++;

        // unsafe wrapper containing block children (hoisting) newline stability
        Safelist relaxed = Safelist.relaxed().addTags("center");
        String[] wrappers = {
            "<p>a</p><center><div>x</div></center><p>b</p>",
            "<center><p>x</p><p>y</p></center>",
            "<div>a</div><unknown><div>b</div></unknown><div>c</div>",
            "<a href=https://ok.com/><div>x</div></a>",
            "<b><p>x</p></b>",
            "<table><tr><td><div>x</div></td></tr></table>",
            "<div>x</div><script>z</script><div>y</div>",
            "<p>x<img src=https://ok.com/a.png></p>",
        };
        for (String w : wrappers) {
            String o1 = Jsoup.clean(w, BASE, relaxed);
            String o2 = Jsoup.clean(o1, BASE, relaxed);
            boolean ok = o1.equals(o2);
            if (!ok) fail++;
            System.out.printf("wrap | %-50s | %-55s | idem=%s%n", w, o1.replace("\n","\\n"), ok);
            if (!ok) System.out.println("   TWICE="+o2.replace("\n","\\n"));
        }

        // text/order stability when dangerous wrappers removed
        String t1 = Jsoup.clean("<div>a<script>evil()</script>b<style>x</style>c</div>", BASE, relaxed);
        System.out.println("text order: " + t1 + " | reparse text=" + Jsoup.parse(t1).body().text());
        if (!Jsoup.parse(t1).body().text().equals("abc")) fail++;

        // selectors after reparse consistent addresses
        String h = "<p>p1</p><a href=rel/x id=l>link</a><img src=/i.png alt=i>";
        String o = Jsoup.clean(h, BASE, Safelist.relaxed().addAttributes("a","id"));
        Document d1 = Jsoup.parse(o);
        Document d2 = Jsoup.parse(Jsoup.clean(o, BASE, Safelist.relaxed().addAttributes("a","id")));
        boolean same = d1.select("a").attr("href").equals(d2.select("a").attr("href"))
            && d1.select("img").attr("src").equals(d2.select("img").attr("src"))
            && d1.select("a#l").size() == d2.select("a#l").size();
        System.out.println("selector/addr consistency: " + same + " href=" + d1.select("a").attr("href") + " src=" + d1.select("img").attr("src"));
        if (!same) fail++;

        // concurrent different bases/safelists
        System.out.println(fail == 0 ? "ALL OK" : fail + " FAILURES");
    }
}

